const D = { energy: .6, scale: 1, speed: 1, density: .55, tide: .5, hue: 200, x: .5, y: .42, style: 'dawn', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- An estuarine tidal flat at low water ----------------------------------
// A dendritic creek network is grown ONCE per seed by flow accumulation over a
// seeded micro-relief (steepest descent to an outlet), so the branching is real
// drainage, not decoration. It is then laid out in ground-plane perspective:
// trunk creeks near, capillary tips far.
// The dramaturgy is the TIDE. It ebbs and floods over minutes on incommensurate
// periods and the water fills the network by BED ELEVATION — trunks first, then
// up the branches to the tips — then sheets over the flats into a sky mirror and
// drains back out. It is never at rest, so it can never read static.
const u0 = Math.min(width, height);
const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function vn(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = hsh(ix, iy), b = hsh(ix + 1, iy), c = hsh(ix, iy + 1), d2 = hsh(ix + 1, iy + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d2) * u * v;
}
function fbm(x, y) { return 0.6 * vn(x, y) + 0.28 * vn(x * 2.03 + 5.1, y * 2.03 - 3.2) + 0.12 * vn(x * 4.1 - 2.3, y * 4.1 + 7.7); }
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

const st = P.style;
const rot = h => (((h + (P.hue - 200)) % 360) + 360) % 360;

// ---- grow the creek network once per seed ----------------------------------
const GW = 96, GH = 64;
if (S.netSeed !== P.seed) {
  S.netSeed = P.seed;
  const Z = new Float32Array(GW * GH), acc = new Float32Array(GW * GH);
  for (let j = 0; j < GH; j++) for (let i = 0; i < GW; i++) {
    // micro-relief falling toward the outlet at the bottom-centre
    Z[j * GW + i] = (1 - j / GH) * 0.55 + Math.abs(i / GW - 0.5) * 0.30
                  + (fbm(i * 0.10 + 3.1, j * 0.10 - 1.7) - 0.5) * 0.30;
  }
  // flow accumulation: every cell drains to its steepest neighbour
  const order = [];
  for (let k = 0; k < GW * GH; k++) { order.push(k); acc[k] = 1; }
  order.sort((a, b) => Z[b] - Z[a]);                   // highest first
  const down = new Int32Array(GW * GH).fill(-1);
  for (let j = 1; j < GH - 1; j++) for (let i = 1; i < GW - 1; i++) {
    const k = j * GW + i;
    let best = -1, bd = 0;
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
      if (!a && !b) continue;
      const k2 = (j + b) * GW + (i + a);
      const d = Z[k] - Z[k2];
      if (d > bd) { bd = d; best = k2; }
    }
    down[k] = best;
  }
  for (let n = 0; n < order.length; n++) { const k = order[n]; const dnk = down[k]; if (dnk >= 0) acc[dnk] += acc[k]; }
  // keep only the cells that carry real flow: those are the creeks
  S.seg = [];
  for (let j = 1; j < GH - 1; j++) for (let i = 1; i < GW - 1; i++) {
    const k = j * GW + i;
    if (acc[k] < 4 || down[k] < 0) continue;
    const dj = (down[k] / GW) | 0, di = down[k] % GW;
    const w = Math.min(1, Math.pow(acc[k], 0.42) / 13);          // Strahler-ish width
    S.seg.push({ u: i / GW, v: j / GH, u2: di / GW, v2: dj / GH, w: w, d: 0 });
  }
  S.seg.sort((a, b) => a.w - b.w);                               // capillaries first, trunks last
  // Cap the network: every wet reach is a line() every frame, and the raw
  // extraction runs to ~2000 — at high water that blew the shape budget.
  // Dropping the narrowest keeps the legible trunk-ward structure.
  const cap = 640;
  if (S.seg.length > cap) S.seg = S.seg.slice(S.seg.length - cap);
  // Bed depth by RANK, not by width. Widths are heavily skewed to capillaries,
  // so keying depth off width left 92% of the network dry until the very top of
  // the tide and then flooded it all at once. By rank the wetted fraction tracks
  // the tide linearly: trunks fill first, then the water climbs out to the tips.
  for (let n = 0; n < S.seg.length; n++) S.seg[n].d = 0.06 + 0.94 * (n / Math.max(1, S.seg.length - 1));
  S.bgKey = null;
}

// ---- cached plate: sky, far shore, flats, the dry incised network ----------
const key = width + 'x' + height + st + P.seed + P.hue + P.density.toFixed(2) + P.y.toFixed(2) + P.scale.toFixed(2);
if (S.bgKey !== key) {
  S.bgKey = key;
  const g = S.bg || (S.bg = createGraphics(width, height));
  if (g.width !== width || g.height !== height) g.resizeCanvas(width, height);
  g.pixelDensity(1); g.colorMode(HSB, 360, 100, 100, 100);
  const hz = height * (0.16 + P.y * 0.42);
  g.push(); g.noStroke();
  // sky
  for (let y = 0; y < hz; y += 2) {
    const v = y / hz;
    if (st === 'silver') g.fill(0, 0, 92 - v * 30);
    else if (st === 'riso') g.fill(rot(v < 0.5 ? 210 : 348), 34 - v * 12, 90 - v * 10);
    else if (st === 'overcast') g.fill(rot(212), 8 + v * 6, 74 - v * 14);
    else g.fill(rot(v < 0.55 ? 216 - v * 20 : 28 + v * 10), 20 + v * 22, 62 + v * 26);   // dawn
    g.rect(0, y, width, 3);
  }
  // far shore: a low dark strip of marsh
  g.fill(st === 'silver' ? 0 : rot(96), st === 'silver' ? 0 : 22, st === 'silver' ? 34 : 26, 90);
  g.beginShape();
  g.vertex(0, hz + 1);
  for (let x = 0; x <= width; x += 14) g.vertex(x, hz - u0 * 0.012 * fbm(x * 0.004 + 9.1, 2.2) - u0 * 0.004);
  g.vertex(width, hz + 1); g.endShape(CLOSE);
  // the flats: wet sand receding to the shore, sky-tinted (they mirror)
  for (let y = Math.floor(hz); y < height; y += 2) {
    const v = (y - hz) / Math.max(1, height - hz);
    if (st === 'silver') g.fill(0, 0, 54 - v * 16);
    else if (st === 'riso') g.fill(rot(210), 16 + v * 8, 72 - v * 18);
    else if (st === 'overcast') g.fill(rot(206), 8 + v * 6, 58 - v * 12);
    else g.fill(rot(28 + v * 8), 12 + v * 12, 56 - v * 8);
    g.rect(0, y, width, 3);
  }
  // ripple-marked sand: texture over flat fill
  const nr = Math.round(60 + P.density * 130);
  for (let n = 0; n < nr; n++) {
    const v = Math.pow(fr(n * 3 + 1), 0.6);
    const y = hz + (height - hz) * v;
    const sc = 0.15 + v * 1.5;
    g.stroke(0, 0, fr(n * 7) > 0.5 ? 100 : 0, 4 + v * 5);
    g.strokeWeight(Math.max(0.6, u0 * 0.0016 * sc));
    g.noFill(); g.beginShape();
    for (let x = -20; x <= width + 20; x += 26) g.vertex(x, y + Math.sin(x * 0.012 + n) * u0 * 0.004 * sc + fbm(x * 0.01, n) * u0 * 0.004 * sc);
    g.endShape();
  }
  g.noStroke();
  // the DRY network, incised into the flats: dark channels with a bright bank lip
  const proj = (u, v) => {
    const vv = Math.pow(v, 1.9);
    return [width / 2 + (u - 0.5) * width * (0.22 + vv * 1.5) * P.scale, hz + (height - hz) * vv];
  };
  for (let n = 0; n < S.seg.length; n++) {
    const sg = S.seg[n];
    const a = proj(sg.u, sg.v), b = proj(sg.u2, sg.v2);
    const dep = Math.pow(sg.v, 1.9);
    const w = Math.max(0.7, u0 * 0.011 * sg.w * (0.12 + dep * 1.5) * P.scale);
    g.strokeCap(ROUND);
    g.stroke(0, 0, 100, 5 + dep * 7); g.strokeWeight(w * 1.9);
    g.line(a[0], a[1], b[0], b[1]);                                   // levee lip catches light
    g.stroke(rot(st === 'silver' ? 0 : 26), st === 'silver' ? 0 : 22, 26 - dep * 6, 60 + dep * 26);
    g.strokeWeight(w);
    g.line(a[0], a[1], b[0], b[1]);                                   // the incised bed
  }
  g.pop();
  S.hz = hz;
}

// ---- the tide ---------------------------------------------------------------
const tideOsc = 0.5 + 0.5 * (0.6 * Math.sin(K.t * 0.041) + 0.28 * Math.sin(K.t * 0.0917 + 2.2) + 0.12 * Math.sin(K.t * 0.1531 + 0.9));
const tide = Math.max(0, Math.min(1.25, (0.18 + P.tide * 0.72) * (0.35 + tideOsc * 1.25) + A.bass * 0.10 + K.intensity * 0.05));
const gain = 0.80 + P.energy * 0.40 + K.intensity * 0.10 + A.rms * 0.20;
const AL = P.alpha / 100;
const hz = S.hz;
const glint = 0.5 + 0.5 * Math.sin(K.t * 1.7) + A.treble * 0.4;

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.bg, 0, 0, width, height);
pop();

const proj = (u, v) => {
  const vv = Math.pow(v, 1.9);
  return [width / 2 + (u - 0.5) * width * (0.22 + vv * 1.5) * P.scale, hz + (height - hz) * vv];
};
// ---- water fills the network by BED ELEVATION: trunks first, then up the tips
noFill(); strokeCap(ROUND);
for (let n = 0; n < S.seg.length; n++) {
  const sg = S.seg[n];
  const bed = 1 - sg.d;                       // deep trunks have a low bed, tips a high one
  const sub = tide - bed;                     // >0 = this reach is carrying water
  if (sub <= 0) continue;
  const a = proj(sg.u, sg.v), b = proj(sg.u2, sg.v2);
  const dep = Math.pow(sg.v, 1.9);
  const w = Math.max(0.8, u0 * 0.011 * sg.w * (0.12 + dep * 1.5) * P.scale) * Math.min(1.5, 0.7 + sub * 2.2);
  const lit = Math.min(1, sub * 3.4);
  if (st === 'silver') stroke(0, 0, 70 + lit * 26 + glint * 6, (55 + lit * 40) * AL);
  else if (st === 'riso') stroke(rot(210), 40, 84 + glint * 8, (55 + lit * 40) * AL);
  else if (st === 'overcast') stroke(rot(206), 14, 72 + lit * 16 + glint * 5, (55 + lit * 40) * AL);
  else stroke(rot(206 - lit * 10), 24 + lit * 12, 66 + lit * 26 + glint * 7, (55 + lit * 40) * AL);
  strokeWeight(w);
  line(a[0], a[1], b[0], b[1]);
}
noStroke();

// ---- at high water the flats drown: a sky mirror sheets over them ----------
if (tide > 0.62) {
  const f = Math.min(1, (tide - 0.62) / 0.38);
  const edgeV = Math.pow(1 - f, 0.8);
  const ey = hz + (height - hz) * edgeV;
  for (let y = Math.floor(ey); y < height; y += 3) {
    const v = (y - hz) / Math.max(1, height - hz);
    const rip = Math.sin(y * 0.09 + K.t * 1.1) * 0.5 + Math.sin(y * 0.031 - K.t * 0.7) * 0.5;
    const al = Math.min(88, (14 + f * 62) * (0.55 + v * 0.7));
    if (st === 'silver') fill(0, 0, 74 + rip * 4, al * AL);
    else if (st === 'riso') fill(rot(210), 36, 80 + rip * 4, al * AL);
    else if (st === 'overcast') fill(rot(208), 12, 66 + rip * 4, al * AL);
    else fill(rot(212 - v * 14), 18 + v * 10, 60 + v * 16 + rip * 4, al * AL);
    rect(0, y, width, 4);
  }
  // the advancing edge itself: a bright lace of foam
  stroke(0, 0, 100, 30 * f * AL); strokeWeight(Math.max(1, u0 * 0.002));
  noFill(); beginShape();
  for (let x = -10; x <= width + 10; x += 22) vertex(x, ey + Math.sin(x * 0.02 + K.t * 0.9) * u0 * 0.004 + fbm(x * 0.008, K.t * 0.1) * u0 * 0.006);
  endShape(); noStroke();
}

// ---- specular glint path + drifting cloud reflections ----------------------
const gx = width * (0.5 + 0.16 * Math.sin(K.t * 0.047));
const ng = Math.round(6 + P.density * 14);
for (let n = 0; n < ng; n++) {
  const v = fr(n * 5 + 2);
  const y = hz + (height - hz) * Math.pow(0.1 + v * 0.9, 1.6);
  const tw = 0.5 + 0.5 * Math.sin(K.t * (1.1 + fr(n) * 2.2) + n);
  fill(0, 0, 100, (5 + tw * 12 + glint * 5) * P.energy * AL);
  ellipse(gx + (fr(n * 3 + 7) - 0.5) * width * 0.20, y, width * (0.02 + v * 0.10), u0 * 0.004 * (0.4 + v));
}
for (let n = 0; n < 3; n++) {
  const cx2 = ((K.t * (5 + n * 4) + fr(n * 11) * 900) % (width * 1.6)) - width * 0.3;
  fill(rot(220), 12, st === 'silver' ? 40 : 34, 7 * AL);
  ellipse(cx2, hz + (height - hz) * (0.18 + n * 0.22), width * 0.5, u0 * 0.05);
}
blendMode(BLEND); drawingContext.shadowBlur = 0; noTint(); noStroke();
